        // Asagi's jealousy is mild, and mostly about the other healer (Story/Asagi.md).
        Cooled(Once, Talk("Asagi_Jealous_Mizore", Asa, DialogueEvent.SoulJealous, Tier.Reactive, When(Most(Element.Water)),
            A("All that ice, little sleet. You'll crack him."), Say("Mizore", "Cold keeps a wound clean, Teacher."),
            A("And warm keeps a patient talking. Who taught you that?"), Say("Mizore", "...You did."))),
        Cooled(Once, Talk("Asagi_Jealous_Akagane", Asa, DialogueEvent.SoulJealous, Tier.Reactive, When(Most(Element.Fire)),
