        Talk("Asagi_Jealous_Frost", Asa, DialogueEvent.SoulJealous, Repeat, When(Most(Element.Water)), A("Too cold. Come and warm up.")),
        Talk("Asagi_Jealous_Fire", Asa, DialogueEvent.SoulJealous, Repeat, When(Most(Element.Fire)), A("Too hot. Come and cool down.")),
        Talk("Asagi_Jealous_Storm", Asa, DialogueEvent.SoulJealous, Repeat, When(Most(Element.Lightning)), A("Too quick. Come and sit.")),
        Talk("Asagi_Jealous_Back", Asa, DialogueEvent.SoulJealous, Repeat, When(Rival), A("Back to the pond. They all come back to the pond.")),
        Talk("Akagane_Hub_First", "Akagane", DialogueEvent.SoulHub, Story, When(LastRunElement(Element.Fire)),
