        Talk("Asagi_Hub_Rest", Asa, DialogueEvent.SoulHub, Repeat, When(LastRunElement(Element.Tide)), A("Dry off. Then go again.")),

        // Crossovers: the bosses on the souls Oni carries, the souls meeting Poguru and cutting into each other's talks,
