        Cooled(4, Talk("Benibana_Intro_Storm", "Benibana", DialogueEvent.BossIntro, Tier.Reactive, When(Holds(Element.Lightning)),
            Say("Benibana", "The drummer girl's spark. She watched me dance with her mouth open. I'm sorry she stayed for the end."))),
