            Say("Hibiki", "...Good. Good! I'll take it. Tell her I'm still sorry about the mud.")),
        Cooled(Once, Talk("Akagane_Poguru", "Akagane", DialogueEvent.SoulPickup, Tier.Reactive, When(Seen("Akagane_Meet_Copper")),
            Say("Akagane", "What is that, at your shoulder."), Say("Poguru", "A SUPPORT dragon!"), Say("Akagane", "The vanguard had a dog once. It was braver."), Say("Poguru", "HEY."))),
        Cooled(Once, Talk("Mizore_Poguru", "Mizore", DialogueEvent.SoulPickup, Tier.Reactive, When(Seen("Mizore_Meet_Collarbone")),
            Say("Mizore", "Your little dragon is running warm. Hold still, creature."), Say("Poguru", "Is it bad? Do I have a fever?"), Say("Mizore", "Dragons don't get fevers."), Say("Poguru", "...Do souls?"), Say("Mizore", "...Take the boon, Oni."))),
        Cooled(Once, Talk("Hibiki_Poguru", "Hibiki", DialogueEvent.SoulPickup, Tier.Reactive, When(Seen("Hibiki_Meet_Name")),
