        Cooled(Once, Talk("Asagi_Poguru", Asa, DialogueEvent.SoulPickup, Tier.Reactive, When(Seen("Asagi_Meet_Fry")),
            P("A FISH. Oni, it's a fish in a bowl, and it's a LADY."), A("And you're a very small dragon. We've all got something, dear."),
            P("...Is it true? Koi that climb the waterfall turn into dragons?"), A("So they say."), P("Why didn't you?"), A("I liked my pond."))),
        Cooled(5, Talk("Hibiki_Cut_Akagane", "Hibiki", DialogueEvent.SoulPickup, Tier.Reactive, When(Holds(Element.Fire), Seen("Hibiki_Meet_Out")),
            Say("Hibiki", "Oni! Hi! Oh, you've got Captain Kettle's fire on you."), Say("Akagane", "Captain Akagane, girl."), Say("Hibiki", "Captain Kettle Akagane."), Say("Akagane", "...Take her boon before I boil."))),
        Cooled(5, Talk("Akagane_Cut_Mizore", "Akagane", DialogueEvent.SoulPickup, Tier.Reactive, When(Holds(Element.Water), Seen("Akagane_Meet_Angry")),
            Say("Akagane", "Fire's ready, Guardsman. Use it."), Say("Mizore", "You'll scorch his hands again, Captain."), Say("Akagane", "Hands heal."), Say("Mizore", "Not in here, they don't."))),
        Cooled(5, Talk("Mizore_Cut_Hibiki", "Mizore", DialogueEvent.SoulPickup, Tier.Reactive, When(Holds(Element.Lightning), Seen("Mizore_Meet_Steady")),
