            P("'I'm not a ninja.' Hehe.")),
        News("Poguru_Talk_Bead", Firsts.Item(PathReward.Bead), 3, P("I've been thinking about Spirit Beads."),
            P("Bosses drop one when they fall. Put it on the boon you use MOST. That's the secret. I made it up. It's still true."), O("...Fine.")),
        News("Poguru_Talk_Thread", Firsts.Item(PathReward.Thread), 3, P("Spirit Threads are rare! Common goes Rare. Rare goes Epic."),
            P("Save it for your favourite boon. Like how I'm your favourite dragon."), O("...You're the only dragon.")),
        News("Poguru_Talk_Scroll", Firsts.Item(PathReward.Scroll), 3, P("Your sword remembers things you don't. The scrolls wake them up."),
            O("...Guard techniques. From before."), P("You remembered something! Quick, remember another one!")),
        News("Poguru_Talk_Spring", Firsts.Item(PathReward.Spring), 3, P("That healing water. Do you think it's the SAME water as the pool?"),
            O("...Maybe."), P("Then I'm never swimming in it again. ...I've never swum in it. Still.")),
        News("Poguru_Talk_Notes", Firsts.Item(PathReward.Notes), 3, P("All those Spirit Notes! They're bits of songs the dead forgot."),
            P("Take them to the flute stand and learn a song. It stays with you every run!"), O("...I know where the flute is.")),
        News("Poguru_Talk_Seal", Firsts.Relic(Relic.Seal), 3, P("That Warlord's Seal is SO heavy. Who gives warlords seals?"),
            O("...He did. One each."), P("Then let's take ALL of them back.")),
        News("Poguru_Talk_Silk", Firsts.Relic(Relic.Silk), 3, P("I made a kite out of the silk. In my head. It flew SO high."),
            P("The real silk's for your songs, though. The really good ranks want it.")),
        News("Poguru_Talk_Legendary", Firsts.Legendary, 3, P("That Legendary boon! The whole wisp went WOOSH."),
            P("Souls only give those away when they REALLY like you."), O("...They don't like me."), P("They REALLY like you.")),
        News("Poguru_Talk_Duo", Firsts.Duo, 3, P("Two souls, ONE boon! They had to agree on something!"), O("...They argued."),
            P("They ALWAYS argue. That's how you know they care.")),
        Talk("Poguru_Talk_Who", Pog, PogTalk, Story, When(), O("Where did you come from."),
            P("Your wisp! The left one. It's cosy. I think I was always there, I just woke up late."),
            P("I'm a dragon! Probably. A small one. Lost. That's my title!")),
        Talk("Poguru_Talk_Cape", Pog, PogTalk, Story, When(Seen("Poguru_Talk_Who"), RunsSince("Poguru_Talk_Who", 1)), O("That red cloth."),
            P("My cape! It smells like festival lanterns. Do you know why?"), O("...No.")),
        Talk("Poguru_Talk_Remember", Pog, PogTalk, Story, When(Runs(3)),
            P("Every time you wake up, you forget a little. So I remember for you!"),
            P("Mostly the wrong things. Did you used to like plums?"), O("...I did.")),
        Talk("Poguru_Talk_Silver", Pog, PogTalk, Story, When(Met(BossKind.Shirogane)),
            P("When the silver lady's near, your wisps go all warm. Is she a friend?"), O("...She was.")),
        // After the Emperor names him a spark of his own fire (Kagetsune_Intro_Spark).
        Talk("Poguru_Talk_Spark", Pog, PogTalk, Story, When(Seen("Kagetsune_Intro_Spark")),
            P("Oni... the big scary one said I'm HIS. A spark of his fire."), P("...Am I his?"), O("You're mine."),
            P("...Okay. Okay! I'm yours. Not his. YOURS.")),
        Talk("Poguru_Talk_Dawn", Pog, PogTalk, Story, When(Clears(1)),
            P("The sun! I'd never seen it! It's very bright. I hid. But I peeked!")),
        // He does Oni's voice at him (voiced as a deep, deadpan impression).
        Talk("Poguru_Talk_Impression", Pog, PogTalk, Story, When(Runs(4)), P("We should name the pool! I'm thinking... Splashy."), O("...No."),
            P("'...No.' 'Hmph.' 'Back in the wisp.' Ooh, look at me, I'm Oni, I'm all brooding."), O("I don't sound like that."),
            P("'I don't sound like that.'"), O("Tch."), P("Splashy it is!")),
        Talk("Poguru_Talk_ImpressionNest", Pog, PogTalk, Repeat, When(Seen("Poguru_Talk_Impression")),
            P("Can my nest be bigger? Pleeease?"), O("No."), P("'No.' Hehe. Still got it.")),
        Talk("Poguru_Talk_Nap", Pog, PogTalk, Repeat, When(),
            P("I was napping. In your wisp. Which is in you. So technically you were napping too.")),
        Talk("Poguru_Talk_Rawr", Pog, PogTalk, Repeat, When(), P("Rawr. That's my fierce face. Was it fierce? Don't answer.")),
        Talk("Poguru_Talk_GhostFire", Pog, PogTalk, Repeat, When(), P("I tried eating a ghost-fire. It tasted like Tuesday.")),
        Talk("Poguru_Talk_Flute", Pog, PogTalk, Repeat, When(), P("Play the flute later? The wisps dance when you do."), O("...Maybe.")),
    };

    const string Pog = "Poguru";
    const DialogueEvent PogTalk = DialogueEvent.PoguruTalk;
    static DialogueLine P(string text) => Say(Pog, text);
    static DialogueLine O(string text) => Say("Oni", text);
    // Asagi, the Water soul, voiced in ASAGI in Tools/generate-voice.mjs.
    const string Asa = "Asagi";
    const DialogueEvent AsaTalk = DialogueEvent.AsagiTalk;
    static DialogueLine A(string text) => Say(Asa, text);
    // Oliver, the Steel soul, voiced in OLIVER in Tools/generate-voice.mjs.
    const string Oli = "Oliver";
    const DialogueEvent OliTalk = DialogueEvent.OliverTalk;
    static DialogueLine Ol(string text) => Say(Oli, text);
    // The tutorial's soldiers, in the soldier voice (SOLDIER in Tools/generate-voice.mjs).
    public const string Soldier = "Ashigaru";
    static DialogueLine S(string text) => Say(Soldier, text);

    // Poguru's word on a first (PoguruFirst): plays once, the moment `key` is first had or seen.
    static Conversation First(string id, string key, params DialogueLine[] lines) =>
        Talk(id, Pog, DialogueEvent.PoguruFirst, Tier.Priority, When(JustGot(key)), lines);

    // Poguru's longer word at the nest on a first had in the last `runs` runs; plays once, ahead of his other talk.
    static Conversation News(string id, string key, int runs, params DialogueLine[] lines) =>
        Talk(id, Pog, PogTalk, Tier.Priority, When(GotWithin(key, runs)), lines);

    // A roast at the temple, resting `cooldown` runs after it plays.
    static Conversation Roast(string id, int cooldown, Req[] requires, params DialogueLine[] lines) =>
        Cooled(cooldown, Talk(id, Pog, DialogueEvent.PoguruWake, Tier.Reactive, requires, lines));

    // A tutorial conversation: never picked, only played by id.
    static Conversation Tut(string id, params DialogueLine[] lines) => Talk(id, Pog, DialogueEvent.Tutorial, Repeat, When(), lines);
}
